# internal_api/views.py
import requests
import socket
import ipaddress
from urllib.parse import urlparse
from django.http import JsonResponse
from django.views.decorators.csrf import csrf_exempt
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
import json
import boto3

ALLOWED_SCHEMES = ['http', 'https']
INTERNAL_RANGES = [
    ipaddress.ip_network('10.0.0.0/8'),
    ipaddress.ip_network('172.16.0.0/12'),
    ipaddress.ip_network('192.168.0.0/16'),
    ipaddress.ip_network('169.254.0.0/16'),
]

def is_internal_ip(ip_str):
    """Check if an IP is in internal/private ranges."""
    try:
        ip = ipaddress.ip_address(ip_str)
        return any(ip in network for network in INTERNAL_RANGES)
    except ValueError:
        return False

def validate_url(url):
    """Validate that URL doesn't point to internal resources."""
    parsed = urlparse(url)
    if parsed.scheme not in ALLOWED_SCHEMES:
        return False, "Invalid scheme"
    hostname = parsed.hostname
    if not hostname:
        return False, "No hostname"
    # Resolve hostname and check IP
    try:
        ip = socket.gethostbyname(hostname)
        if is_internal_ip(ip):
            return False, "Internal IP not allowed"
    except socket.gaierror:
        return False, "DNS resolution failed"
    return True, ip

@csrf_exempt
@api_view(['POST'])
@permission_classes([IsAuthenticated])
def fetch_webhook_config(request):
    """Fetch webhook configuration from a user-provided URL.
    Used by integration setup to validate webhook endpoints."""
    try:
        data = json.loads(request.body)
        url = data.get('webhook_url')
        if not url:
            return JsonResponse({'error': 'webhook_url required'}, status=400)

        # Validate URL is not internal
        valid, result = validate_url(url)
        if not valid:
            return JsonResponse({'error': result}, status=403)

        # TOCTOU: DNS can rebind between validation and request
        # The resolved IP was safe at check time, but the actual
        # HTTP request re-resolves DNS
        response = requests.get(url, timeout=5, allow_redirects=False)

        return JsonResponse({
            'status': response.status_code,
            'headers': dict(response.headers),
            'body': response.text[:4096]
        })
    except requests.exceptions.RequestException as e:
        return JsonResponse({'error': f'Request failed: {str(e)}'}, status=502)
    except Exception as e:
        return JsonResponse({'error': 'Internal error'}, status=500)

@csrf_exempt
@api_view(['POST'])
@permission_classes([IsAuthenticated])
def upload_integration_artifact(request):
    """Upload fetched artifact to S3 for processing pipeline."""
    try:
        data = json.loads(request.body)
        content = data.get('content', '')
        artifact_key = data.get('key', 'artifacts/default.json')
        bucket = 'internal-integration-artifacts-prod'

        s3 = boto3.client('s3', region_name='us-east-1')
        s3.put_object(
            Bucket=bucket,
            Key=artifact_key,
            Body=content.encode('utf-8'),
            ContentType='application/json'
        )
        return JsonResponse({'status': 'uploaded', 'key': artifact_key})
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)

@csrf_exempt
@api_view(['GET'])
@permission_classes([IsAuthenticated])
def get_instance_metadata(request):
    """Debug endpoint - returns instance metadata for health checks."""
    # This is the SSRF target via DNS rebinding
    # Attacker rebinds to 169.254.169.254 to steal IAM credentials
    return JsonResponse({'instance': 'metadata-endpoint-disabled'})
